function noteItem(n){return '<li class="nlog__item"><div class="nlog__head"><b>'+esc(who(n.by))+'</b><span>'+d(n.at)+' '+tm(n.at)+'</span>'+(n.by&&n.by===ME?'<button type="button" class="nlog__del" data-notedel="'+esc(n.id)+'">'+esc(M.ntRemove)+'</button>':'')+'</div><div class="nlog__text">'+esc(n.text)+'</div></li>'}
function noteBox(ref){var list=notesFor(ref);return '<div class="nlog" data-ref="'+esc(ref)+'"><p class="sec-t">'+esc(M.ntTitle)+'</p><ul class="nlog__list">'+list.map(noteItem).join('')+'</ul><p class="nlog__empty"'+(list.length?' hidden':'')+'>'+esc(M.ntEmpty)+'</p><div class="note"><textarea rows="2" placeholder="'+esc(M.ntPh)+'"></textarea><div class="note__bar"><button class="btn btn-red" type="button" data-noteadd disabled>'+esc(M.ntAdd)+'</button><span class="note__st"></span></div></div></div>'}
function setDirty(w,v){var has=!!String(v||'').trim();w.classList.toggle('dirty',has);$('[data-noteadd]',w).disabled=!has;$('.note__st',w).textContent=has?M.ntNot:''}
function restoreDrafts(){$$('.nlog').forEach(function(b){var v=S.drafts[b.dataset.ref];if(v){var ta=$('textarea',b);ta.value=v;setDirty($('.note',b),v)}})}
function refreshNotes(ref){$$('.nlog').forEach(function(b){if(b.dataset.ref!==ref)return;var list=notesFor(ref);$('.nlog__list',b).innerHTML=list.map(noteItem).join('');$('.nlog__empty',b).hidden=!!list.length});$$('tr.row').forEach(function(r){var det=r.nextElementSibling;if(det&&det.dataset.d===ref){var c=r.querySelector('[data-nc]');if(c)c.textContent=notesFor(ref).length}})}
function feeSel(m){if(m.staff)return '—';var paid=m.fee==='paid',a=m.advanced,live=a&&(a.status==='active'||a.status==='past_due');return '<select data-set="fee" data-email="'+esc(m.email)+'" class="'+(paid?'fee-paid':'')+'" aria-label="Fee"><option value="free"'+(paid?'':' selected')+'>'+esc(M.feeFree)+'</option><option value="paid"'+(paid?' selected':'')+'>'+esc(M.feePaid)+'</option></select>'+(live?'<span class="sub adv'+(a.status==='past_due'?' bad':'')+'">'+esc(M.stripeVia)+' · '+esc(a.status==='past_due'?M.advPastDue:(a.cancelAtPeriodEnd?M.advEnds:M.advUntil))+(a.status==='past_due'?'':' '+d(a.until))+'</span>':'')}
function loadBill(){return call('GET','/api/staff/billing').then(function(j){if(j.status==='ok')S.bill=j}).catch(function(){})}
function billBar(){var b=S.bill;if(!b)return '';var st=b.stripe==='live'?M.billLive:b.stripe==='test'?M.billTest:M.billNone;
 return '<div class="bill"><div class="bl"><b>'+esc(M.billH)+'</b><span class="bf"><select data-billcur>'+(b.currencies||['hkd']).map(function(c){return '<option value="'+c+'"'+(c===b.currency?' selected':'')+'>'+c.toUpperCase()+'</option>'}).join('')+'</select><input type="number" min="0" step="1" data-billamt value="'+(b.amount?b.amount/100:'')+'" placeholder="0"><button type="button" class="btn btn-line" data-billsave>'+esc(M.billSave)+'</button></span></div>'
  +'<div class="bs"><span class="'+(b.stripe==='none'?'no':'ok')+'">'+esc(M.billStripe)+': '+esc(st)+'</span><span class="'+(b.webhook?'ok':'no')+'">'+esc(M.billHook)+': '+esc(b.webhook?M.billHookOk:M.billHookNo)+'</span><span>'+esc(b.ready?M.billOn:M.billOff)+'</span></div></div>'}
document.addEventListener('click',function(e){var sv=e.target.closest('[data-billsave]');if(!sv)return;var amt=Number($('[data-billamt]').value),cur=$('[data-billcur]').value;if(!(amt>=0)){toast(M.billBad);return}sv.disabled=true;
 call('POST','/api/staff/billing',{currency:cur,amount:amt}).then(function(j){sv.disabled=false;if(j.status!=='ok')throw j;S.bill=j;render();toast(M.billSaved)}).catch(function(){sv.disabled=false;toast(M.billBad)})});
