function rtWait(r){return r&&(r.status==='queued'||r.status==='running')}
function rtBadge(r){return '<span class="rt b-'+esc(r.band||'emerging')+'" title="'+esc(BANDS[r.band]||'')+'">'+r.score+'</span>'}
function rtCell(m){if(m.staff)return '—';var r=m.rating;if(!r)return '<span class="rt-s">'+esc(M.rtNone)+'</span>';
 if(rtWait(r))return (r.score!=null?rtBadge(r)+' ':'')+'<span class="rt-s wait">'+esc(r.status==='queued'?M.rtQueued:M.rtRunning)+'</span>';
 if(r.status==='done')return rtBadge(r);
 return (r.score!=null?rtBadge(r)+' ':'')+'<span class="rt-s">'+esc(r.status==='no_website'?M.rtNoWeb:r.status==='no_company'?M.rtNoCo:M.rtFailed)+'</span>'}
function rtPanel(m){if(m.staff)return '';var r=m.rating||{},h='<p class="sec-t">'+esc(M.rtTitle)+'</p><div class="rtbox">';
 if(r.score!=null&&(r.status==='done'||rtWait(r)||r.status==='failed'||r.status==='no_website')){h+='<div class="rtbig"><b>'+r.score+'</b><span class="bd">'+esc(BANDS[r.band]||'')+'</span>'+(r.confidence?'<span class="rt-s">'+esc(M.rtConf)+': '+esc(M['conf_'+r.confidence]||r.confidence)+'</span>':'')+'</div>'}
 var st=!r.status?M.rtNone:rtWait(r)?(r.status==='queued'?M.rtQueued:M.rtRunning):r.status==='no_website'?M.rtNoWeb:r.status==='no_company'?M.rtNoCo:r.status==='failed'?M.rtFailed:'';
 h+='<div class="rtmeta">'+(st?'<b>'+esc(st)+'</b>'+(r.error?' · '+esc(r.error):'')+'<br>':'')
  +(r.at&&r.status==='done'?esc(M.rtOn)+': '+d(r.at)+(r.prevAt?'':'')+'<br>':'')
  +(r.website?esc(M.rtSite)+': <a href="'+esc(/^https?:\/\//i.test(r.website)?r.website:'#')+'" target="_blank" rel="noopener">'+esc(r.website.replace(/^https?:\/\//,''))+'</a>'+(r.websiteSource?' ('+esc(M['src_'+r.websiteSource]||r.websiteSource)+')':'')+'<br>':'')
  +(r.status==='no_website'?esc(M.rtNoWebHelp)+'<br>':'')
  +(r.history&&r.history.length>1?esc(M.rtPrev)+': '+r.history.slice(0,-1).reverse().slice(0,3).map(function(x){return x.score+' ('+d(x.at)+')'}).join(', '):'')+'</div>';
 if(r.status==='done'&&r.dims){h+='<div class="rtdims">'+DIMS.map(function(id){var x=r.dims.filter(function(y){return y.id===id})[0]||{},na=x.score==null;return '<div class="rtdim'+(na?' na':'')+'"><span>'+esc(M['dim_'+id])+'</span><span class="rtbar">'+(na?'':'<i style="width:'+x.score+'%"></i>')+'</span><span>'+(na?'—':x.score)+'</span></div>'}).join('')+'</div>';
  if(r.checks&&r.checks.length)h+='<details class="rtchk"><summary>'+esc(M.rtChecks)+'</summary><ul>'+r.checks.map(function(c){return '<li><span class="'+(c.pass===true?'ok':c.pass===false?'no':'na')+'">'+esc(c.pass===true?M.rtPass:c.pass===false?M.rtFail:M.rtNA)+'</span><span>'+esc(c.en)+' · '+esc(c.zh)+(c.evidence&&!/^https?:/.test(c.evidence)?' <span class="rt-s">('+esc(c.evidence)+')</span>':'')+'</span></li>'}).join('')+'</ul></details>'}
 var site=m.rating&&m.rating.website||'';
 h+='<div class="rtrun"><label>'+esc(M.rtSiteLabel)+'</label><input type="url" data-rtsite="'+esc(m.email)+'" placeholder="https://" value="'+esc(site)+'"><button type="button" class="btn btn-line" data-rtrun="'+esc(m.email)+'"'+(rtWait(r)?' disabled':'')+'>'+esc(r.status?M.rtRerun:M.rtRun)+'</button></div>';
 if(m.lastDx)h+='<div class="rtdx">'+esc(M.rtDx)+': '+rtBadge(m.lastDx)+' '+d(m.lastDx.at)+'</div>';
 return h+'<p class="rt-s" style="margin:10px 0 0;white-space:normal">'+esc(M.rtAbout)+'</p></div>'}
var rtT=null,rtN=0;
function rtPoll(){clearTimeout(rtT);if(!S.members.some(function(m){return rtWait(m.rating)})){rtN=0;return}if(++rtN>60)return;
 rtT=setTimeout(function(){call('GET','/api/staff/members').then(function(j){if(j.status!=='ok')return;var by={};j.members.forEach(function(x){by[x.email]=x});var ch=false;S.members.forEach(function(m){var x=by[m.email];if(x&&JSON.stringify(x.rating)!==JSON.stringify(m.rating)){m.rating=x.rating;ch=true}});if(ch&&!document.querySelector('.rtrun input:focus'))render();rtPoll()}).catch(rtPoll)},demo?2500:8000)}
document.addEventListener('input',function(e){var ta=e.target;if(ta.tagName!=='TEXTAREA')return;var b=ta.closest('.nlog');if(!b)return;S.drafts[b.dataset.ref]=ta.value;setDirty(ta.closest('.note'),ta.value)});
document.addEventListener('click',function(e){
 var add=e.target.closest('[data-noteadd]');
 if(add){var b=add.closest('.nlog'),ref=b.dataset.ref,ta=$('textarea',b),st=$('.note__st',b);add.disabled=true;add.textContent=M.ntAdding;
  call('POST','/api/staff/note',{email:ref,text:ta.value}).then(function(j){if(j.status!=='ok'||!j.note)throw j;(NOTES[ref]=NOTES[ref]||[]).push(j.note);delete S.drafts[ref];ta.value='';$('.note',b).classList.remove('dirty');add.textContent=M.ntAdd;refreshNotes(ref);st.textContent=M.ntAdded;toast(M.ntOK)})
   .catch(function(){add.disabled=false;add.textContent=M.ntAdd;st.textContent=M.ntFail;toast(M.fail)});return}
 var del=e.target.closest('[data-notedel]');
 if(del){if(!confirm(M.ntConfirm))return;var ref2=del.closest('.nlog').dataset.ref,id=del.dataset.notedel;del.disabled=true;
  call('POST','/api/staff/note',{email:ref2,remove:id}).then(function(j){if(j.status!=='ok')throw j;NOTES[ref2]=notesFor(ref2).filter(function(n){return n.id!==id});refreshNotes(ref2);toast(M.ntRemoved)}).catch(function(){del.disabled=false;toast(M.fail)});return}
 var run=e.target.closest('[data-rtrun]');
 if(run){var em=run.dataset.rtrun,inp=$('[data-rtsite="'+CSS.escape(em)+'"]'),m=S.members.filter(function(x){return x.email===em})[0],body={email:em},v=inp?inp.value.trim():'';
  if(v&&(!m.rating||v!==m.rating.website))body.website=v;run.disabled=true;
  call('POST','/api/staff/rate',body).then(function(j){if(j.status==='bad_website'){run.disabled=false;toast(M.rtBadSite);return}if(j.status!=='ok')throw j;m.rating=j.rating||{status:'queued'};toast(M.rtStarted);render();rtPoll()}).catch(function(){run.disabled=false;toast(M.fail)});return}
});
