function evEnd(e){var d=e.end||e.start||'';return d.length===7?d+'-31':d}
function evWhen(e){var M3=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'],s=(e.start||'').split('-');if(!s[0])return '—';var lab=(e.dateLabel||{}).en;var t=lab?lab+' '+s[0]:((s[2]?(+s[2])+' ':'')+M3[(+s[1]||1)-1]+' '+s[0]);if(e.end&&e.end!==e.start){var x=e.end.split('-');if(!lab)t+=' – '+(x[2]?(+x[2])+' ':'')+M3[(+x[1]||1)-1]+' '+x[0]}return t+(e.tbc?' · TBC':'')}
