 h+='<div class="evform">';
 h+='<div class="evf"><label class="evl">Type 類型</label><div class="evradio"><label><input type="radio" name="evkind" value="cgbb"'+(e.kind!=='partner'?' checked':'')+'> <b>CGBB event 品信會活動</b> <span class="note">— shown at the top of the Events section 顯示於活動欄目最上方</span></label><label><input type="radio" name="evkind" value="partner"'+(e.kind==='partner'?' checked':'')+'> <b>Partner event 合作夥伴活動</b> <span class="note">— shown lower down, under “From our founders and partners” 顯示於下方合作夥伴活動</span></label></div></div>';
 h+=evPair('title','Event title 活動名稱 *',e.title,{max:200});
 h+=evPair('by','Organiser 主辦方',e.by,{max:120,hint:'Shown above the title, e.g. “CGBB × Global Connect Show” or “Yicai · Founding strategic partner”. 顯示於標題上方。'});
 h+='<div class="evf"><label class="evl">Date 日期 *</label><div class="evradio row"><label><input type="radio" name="evdm" value="day"'+(month?'':' checked')+'> Exact date 具體日期</label><label><input type="radio" name="evdm" value="month"'+(month?' checked':'')+'> Month only 僅月份</label></div>'
  +'<div class="evdates"><div><span class="evlang">Starts 開始</span><input type="'+(month?'month':'date')+'" data-ev="start" value="'+esc(month?e.start:(e.start||''))+'"></div><div><span class="evlang">Ends (optional) 結束（可選）</span><input type="'+(month?'month':'date')+'" data-ev="end" value="'+esc(e.end||'')+'"></div></div>'
  +'<label class="evck"><input type="checkbox" data-ev="tbc"'+(e.tbc?' checked':'')+'> Date to be confirmed — show “Date TBC” 日期待定</label></div>';
 h+=evPair('dateLabel','Date label (optional) 日期顯示（可選）',e.dateLabel,{max:40,hint:'Only if the automatic date needs replacing, e.g. “Nov–Dec”. Leave blank normally. 一般留空。',ph:{en:'e.g. Nov–Dec',zh:'例如：11月–12月'}});
 h+=evPair('city','Location 地點',e.city,{max:200,ph:{en:'e.g. Hong Kong',zh:'例如：香港'}});
 h+=evPair('text','Description 簡介',e.text,{rows:5,max:2000});
 h+='<div class="evf"><label class="evl">Photo or image (optional) 圖片（可選）</label><div class="evimgbox">'+(e.image?'<img src="'+esc(e.image)+'" alt="">':'<div class="note">No image 沒有圖片</div>')+'</div><div class="evbtns"><button type="button" class="btn btn-line" data-ev-img>'+(e.image?'Replace image 更換圖片':'Upload image 上傳圖片')+'</button>'+(e.image?'<button type="button" class="linkbtn" data-ev-img-rm>Remove image 移除圖片</button>':'')+'<input type="file" accept="image/png,image/jpeg,image/gif,image/webp" data-ev-file hidden></div><div class="note">JPG, PNG or GIF. Large photos are resized automatically. 大圖會自動縮小。</div></div>';
 h+='<div class="evf"><label class="evl">Link (optional) 連結（可選）</label><input type="url" data-ev="url" placeholder="https://" value="'+esc(e.url||'')+'"></div>';
