 var ed=t.closest('[data-ev-edit]');if(ed){var x=S.evs.filter(function(v){return v.id===ed.dataset.evEdit})[0];if(x){S.evEd=JSON.parse(JSON.stringify(x));S.evEd.items=S.evEd.items||[];render();scrollTo(0,0)}return}
 if(t.closest('[data-ev-back]')){e.preventDefault();S.evEd=null;render();return}
 if(t.closest('[data-ev-img]')){$('[data-ev-file]').click();return}
