 if(t.closest('[data-ev-item-add]')){evRead();S.evEd.items.push({date:{en:'',zh:''},title:{en:'',zh:''}});render();return}
 var idl=t.closest('[data-ev-item-del]');if(idl){evRead();S.evEd.items.splice(+idl.dataset.evItemDel,1);render();return}
